fn solve(n: i8) -> Vec<char> {
    // Convert n to usize for indexing
    let n = n as usize;
    let mut result = Vec::with_capacity(n);

    // We use the 4‐periodic pattern "a a b b"
    for i in 0..n {
        let ch = match i % 4 {
            0 | 1 => 'a',
            _      => 'b',
        };
        result.push(ch);
    }

    result
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_small() {
        assert_eq!(solve(1), vec!['a']);
        assert_eq!(solve(2), vec!['a', 'a']);
        assert_eq!(solve(3), vec!['a', 'a', 'b']);
        assert_eq!(solve(4), vec!['a', 'a', 'b', 'b']);
        assert_eq!(solve(5), vec!['a', 'a', 'b', 'b', 'a']);
    }

    #[test]
    fn test_constraint() {
        for n in 1..10 {
            let s = solve(n);
            // Check length
            assert_eq!(s.len(), n as usize);
            // Check only a/b
            assert!(s.iter().all(|&c| c == 'a' || c == 'b'));
            // Check s[i] != s[i+2]
            for i in 0..(n as usize).saturating_sub(2) {
                assert_ne!(s[i], s[i + 2], "Failed at n={}, i={}", n, i);
            }
        }
    }
}